import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Agent Loop","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/agent-loop.md","filePath":"concepts/agent-loop.md","lastUpdated":1790405974000}'),c={name:"concepts/agent-loop.md"};function d(s,e,l,n,i,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="agent-loop" tabindex="-1">Agent Loop <a class="header-anchor" href="#agent-loop" aria-label="Permalink to &quot;Agent Loop&quot;">​</a></h1><p>固定循环，不是可拖拽的图。入口是 <code>chat_send</code> → <code>core::start_turn</code>，循环在 <code>core::plan::run_agent_loop</code>。阶段顺序如下；没有单独实现的阶段，写的是现在实际落在这一步的行为。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>会话 → 模式 → 意图 → 槽位 → 策略 → 规划 → 路由 → 执行 → 验证 → 记忆 → 回复</span></span></code></pre></div><p>有工具调用时，验证和记忆之后回到规划，直到模型不再调用工具或用户中止。</p><h2 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h2><div class="mermaid">flowchart TD session[&quot;会话&quot;] --&gt; mode[&quot;模式&quot;] mode --&gt; intent[&quot;意图&quot;] intent --&gt; slot[&quot;槽位&quot;] slot --&gt; policy[&quot;策略&quot;] policy --&gt; plan[&quot;规划&quot;] plan --&gt; calls{&quot;有 tool call?&quot;} calls --&gt;|否| memory[&quot;记忆&quot;] memory --&gt; reply[&quot;回复&quot;] calls --&gt;|是| route[&quot;路由&quot;] route --&gt; exec[&quot;执行&quot;] exec --&gt; check[&quot;验证&quot;] check --&gt; memory2[&quot;记忆&quot;] memory2 --&gt; plan</div><h2 id="会话" tabindex="-1">会话 <a class="header-anchor" href="#会话" aria-label="Permalink to &quot;会话&quot;">​</a></h2><p>确保或新建会话。新建时可写入分组；若前端指定了 Agent，则预绑 <code>agent_id</code> 与对应 <code>workspace_dir</code>。未指定时 workspace 暂取全局默认 Agent，角色留给决策层（意图选角或用户稍后手选）。会话顶栏可切换主 Agent（<code>session_set_agent</code>），切换时同步 workspace。历史消息保存在该会话里。本轮注册中止通道，<code>chat_abort</code> 只置位。</p><h2 id="模式" tabindex="-1">模式 <a class="header-anchor" href="#模式" aria-label="Permalink to &quot;模式&quot;">​</a></h2><p>把前端传入的字符串收成 Ask、Agent、Search，缺省 Ask。选择存在本机 <code>localStorage</code>，不写入会话。</p><ul><li>Ask：不带工具，不注入知识库和技能。</li><li>Search：不带工具，知识库最多 8 条。</li><li>Agent：带内置工具和 MCP，注入技能，知识库最多 3 条。</li></ul><h2 id="意图" tabindex="-1">意图 <a class="header-anchor" href="#意图" aria-label="Permalink to &quot;意图&quot;">​</a></h2><p><code>intent::run</code> 只看用户原文，不看模式。结果是 <code>Intent</code>：类别（闲聊、工具执行、内容发布、账号查询、未识别）、置信度、命中关键词、来源、<code>needs_tools</code>。Agent 和 Search 把它写进系统提示词；置信度过低且未识别则不写。Agent 模式下，若会话尚未绑定且用户未手选角色，可用意图挑角色（置信度低于 0.5 不改角色）。用户手选或会话已绑定优先。不改变模式，也不短路循环。</p><h2 id="槽位" tabindex="-1">槽位 <a class="header-anchor" href="#槽位" aria-label="Permalink to &quot;槽位&quot;">​</a></h2><p>当前没有槽位抽取，不从原句拆出平台、路径、账号等参数。和槽位最接近的是意图里的命中关键词，仍留在意图结果中，不单独填槽。</p><h2 id="策略" tabindex="-1">策略 <a class="header-anchor" href="#策略" aria-label="Permalink to &quot;策略&quot;">​</a></h2><p>决定这一轮能不能动工具，以及工具执行前怎么授权。只有 Agent 模式把工具定义放进模型请求。执行前按权限模式裁决 allow / ask / deny，可按会话记住；再叠加 Agent 覆盖和 workspace 约束。</p><h2 id="规划" tabindex="-1">规划 <a class="header-anchor" href="#规划" aria-label="Permalink to &quot;规划&quot;">​</a></h2><p>没有独立规划器。规划就是 <code>stream_chat</code>：模型决定直接回复，还是发出 tool call。请求前若上下文超过窗口约 85%，先截断旧消息。选模型发生在这一轮开始：会话绑定，其次手动激活，再次自动路由。用户中止与这次流式请求赛跑。</p><h2 id="路由" tabindex="-1">路由 <a class="header-anchor" href="#路由" aria-label="Permalink to &quot;路由&quot;">​</a></h2><p>模型请求失败时标记该 profile，下一轮可以换。成功且存在 tool call 时，按工具名分流：<code>spawn_agent</code>、MCP、内置工具（bash / read_file / write_file / web_fetch / search_files / glob_files）。同一轮里的多个工具按顺序路由，不并行。</p><h2 id="执行" tabindex="-1">执行 <a class="header-anchor" href="#执行" aria-label="Permalink to &quot;执行&quot;">​</a></h2><p>每个工具在权限通过后执行。文件操作限制在会话 workspace 内。<code>spawn_agent</code> 再跑一层短循环，最多 30 轮，不落库、不弹权限、不能再套子 Agent，工作目录不得超出父会话。</p><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>没有单独的验收步骤。工具失败把错误内容写回；过长结果会截断。模型请求失败则中止本轮并记失败，不把错误当成正常回复。</p><h2 id="记忆" tabindex="-1">记忆 <a class="header-anchor" href="#记忆" aria-label="Permalink to &quot;记忆&quot;">​</a></h2><p>用户消息、工具展示和助手回复写入会话并落库。知识库按模式注入提示词，不是每轮改写历史。本轮耗时、模式、意图和 token 写入会话链路。</p><h2 id="回复" tabindex="-1">回复 <a class="header-anchor" href="#回复" aria-label="Permalink to &quot;回复&quot;">​</a></h2><p>没有 tool call 时写入助手回复，发出结束，并带上本轮 token。有工具结果时不在这里结束，回到规划。</p><h2 id="代码" tabindex="-1">代码 <a class="header-anchor" href="#代码" aria-label="Permalink to &quot;代码&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>位置</th></tr></thead><tbody><tr><td>编排入口</td><td><code>src-tauri/src/core/turn.rs</code>（<code>start_turn</code>）+ <code>context.rs</code> / <code>pipeline.rs</code></td></tr><tr><td>会话</td><td><code>src-tauri/src/core/session/</code>（<code>run</code>）</td></tr><tr><td>意图理解</td><td><code>src-tauri/src/core/intent/</code></td></tr><tr><td>决策/路由</td><td><code>src-tauri/src/core/decision/</code></td></tr><tr><td>规划编排</td><td><code>src-tauri/src/core/plan/</code></td></tr><tr><td>执行工具</td><td><code>src-tauri/src/core/execute/</code>（委托 <code>agents/dispatch.rs</code>）</td></tr><tr><td>记忆/知识</td><td><code>src-tauri/src/core/memory/</code>、<code>chat/repository.rs</code></td></tr><tr><td>响应生成</td><td><code>src-tauri/src/core/response/</code></td></tr><tr><td>编排入口</td><td><code>src-tauri/src/chat/service.rs</code></td></tr></tbody></table><p>分层流程图源文件在仓库 <a href="./../drawio/"><code>docs/drawio/</code></a>（可导出 SVG 后挂到本站）。</p>',32)])])}const q=t(c,[["render",d]]);export{u as __pageData,q as default};
